const parseIntE = s => {
  const n = Number(s);
  return isNaN(n) ? Either.left("Not a number") : Either.right(Math.trunc(n));
};
const reciprocal = x => x === 0 ?
                        Either.left("Division by zero") :
                        Either.right(1.0 / x);

parseIntE("5").flatMap(reciprocal);
